import { MakeLogicType, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'

import { HogFunctionType } from '~/types'

import { BATCH_EXPORT_ICON_MAP } from '../batch-exports/BatchExportIcon'
import { humanizeBatchExportDescription } from '../batch-exports/utils'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface nonHogFunctionsLogicValues {
    hogFunctionBatchExports: HogFunctionType[] | null
    hogFunctionBatchExportsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface nonHogFunctionsLogicActions {
    loadHogFunctionBatchExports: () => any
    loadHogFunctionBatchExportsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadHogFunctionBatchExportsSuccess: (
        hogFunctionBatchExports: HogFunctionType[],
        payload?: any
    ) => {
        hogFunctionBatchExports: HogFunctionType[]
        payload?: any
    }
}

export type nonHogFunctionsLogicType = MakeLogicType<nonHogFunctionsLogicValues, nonHogFunctionsLogicActions>

export const nonHogFunctionsLogic = kea<nonHogFunctionsLogicType>([
    path((key) => ['scenes', 'data-pipelines', 'utils', 'nonHogFunctionsLogic', key]),

    loaders(() => ({
        hogFunctionBatchExports: [
            null as HogFunctionType[] | null,
            {
                loadHogFunctionBatchExports: async () => {
                    const response = await api.batchExports.list()
                    const results = response.results
                    const hogFunctions: HogFunctionType[] = []

                    for (const batchExport of results) {
                        // TODO - exclude Workflows from here
                        hogFunctions.push({
                            id: `batch-export-${batchExport.id}`,
                            name: batchExport.name,
                            description: humanizeBatchExportDescription(batchExport.destination.type),
                            type: 'destination',
                            created_by: null,
                            created_at: batchExport.created_at,
                            updated_at: batchExport.created_at,
                            enabled: !batchExport.paused,
                            hog: '',
                            icon_url: BATCH_EXPORT_ICON_MAP[batchExport.destination.type],
                            execution_order: undefined,
                        })
                    }

                    return hogFunctions
                },
            },
        ],
    })),
])
